const response = $input.first().json;

const WABA_ID = '1213652250554863';

// Validar la cuenta consultada
if (String(response?.id) !== WABA_ID) {
  throw new Error('Respuesta de Meta: WABA ID inesperado');
}

const groups = response.pricing_analytics?.data;
const soloId = Object.keys(response).length === 1;

let points = [];
let sinDatosMeta = false;

// Procesar estadísticas cuando existen
if (Array.isArray(groups)) {
  points = groups.flatMap(group => {
    if (!Array.isArray(group.data_points)) {
      throw new Error('data_points inválido');
    }

    return group.data_points;
  });

} else if (soloId) {

  // Respuesta válida de Meta, sin estadísticas
  // El cero es provisional, no confirmado
  sinDatosMeta = true;

} else {
  throw new Error(
    'Meta devolvió una respuesta de estadísticas inesperada'
  );
}

let gratuitos = 0;
let regulares = 0;
let otros = 0;
let total = 0;
let costo = 0;

for (const point of points) {
  const volume = Number(point.volume);
  const cost = Number(point.cost);

  if (
    !Number.isInteger(volume) ||
    volume < 0 ||
    point.cost === null ||
    point.cost === undefined ||
    !Number.isFinite(cost) ||
    cost < 0
  ) {
    throw new Error('Datos de volumen o costo incompletos');
  }

  total += volume;
  costo += cost;

  if (point.pricing_type === 'FREE_CUSTOMER_SERVICE') {
    gratuitos += volume;

  } else if (point.pricing_type === 'REGULAR') {
    regulares += volume;

  } else {
    otros += volume;
  }
}

return [{
  json: {
    waba_id: String(response.id),

    mes: $now.setZone('America/Mexico_City')
      .startOf('month').toISODate(),

    mensajes_total: total,
    mensajes_gratis: gratuitos,
    mensajes_regulares: regulares,
    mensajes_otros: otros,

    costo_estimado_usd: Number(costo.toFixed(4)),

    umbral_mensajes_actual:
      Math.floor(total / 1000) * 1000,

    proximo_umbral_mensajes:
      (Math.floor(total / 1000) + 1) * 1000,

    sin_datos_meta: sinDatosMeta,

    consultado_en: new Date().toISOString()
  }
}];

const registro = $input.first().json;

// Configuración editable de alertas
const PASO_MENSAJES = 1000;
const PASO_COSTO_USD = 20;

// Estadísticas actuales
const mensajes = Number(registro.mensajes_total);
const costo = Number(registro.costo_estimado_usd);

// Últimos umbrales notificados
const ultimoMensajes = Number(
  registro.ultimo_umbral_mensajes_avisado ?? 0
);

const ultimoCosto = Number(
  registro.ultimo_umbral_costo_avisado_usd ?? 0
);

// Validación
if (
  ![mensajes, costo, ultimoMensajes, ultimoCosto]
    .every(Number.isFinite)
) {
  throw new Error("Estadísticas de alertas inválidas");
}

// Umbrales alcanzados
const umbralMensajes =
  Math.floor(mensajes / PASO_MENSAJES) * PASO_MENSAJES;

const umbralCosto =
  Math.floor(costo / PASO_COSTO_USD) * PASO_COSTO_USD;

// Comprobar si ya se notificaron
const alertaMensajes = umbralMensajes > ultimoMensajes;
const alertaCosto = umbralCosto > ultimoCosto;

// Construir mensajes
const alertas = [];

if (alertaMensajes) {
  alertas.push(
    `Se alcanzaron ${mensajes} mensajes este mes. ` +
    `Nuevo umbral: ${umbralMensajes}.`
  );
}

if (alertaCosto) {
  alertas.push(
    `El gasto mensual alcanzó US$${costo.toFixed(2)}. ` +
    `Nuevo umbral: US$${umbralCosto}.`
  );
}

return [{
  json: {
    ...registro,

    debe_notificar: alertas.length > 0,
    alerta_mensajes: alertaMensajes,
    alerta_costo: alertaCosto,

    umbral_mensajes_detectado: umbralMensajes,
    umbral_costo_detectado: umbralCosto,

    alertas
  }
}];

